CREATE OR REPLACE VIEW DBP_MSI_VIEW_AIS_INT.MV_LAND_SPR_ZU
(
mandant_id
,spr_id
,land_bez
)
AS
SELECT
v03.mandant_id
,v01.spr_id
,land_bez
FROM
(
SELECT
mandant_id
,spr_id
,
CASE WHEN mandant_id = 1 THEN 'Bewertete Kennzahlen werden ab sofort in LANDESWÄHRUNG angezeigt.'
WHEN mandant_id = 2 THEN  '\u0048\u006F\u0064\u006E\u006F\u0074\u0079\u0020\u0075\u006B\u0061\u007A\u0061\u0074\u0065\u006C\u016F\u0020\u0073\u0065\u0020\u007A\u0061\u010D\u006E\u006F\u0075\u0020\u007A\u006F\u0062\u0072\u0061\u007A\u006F\u0076\u0061\u0074\u0020\u0076\u0020\u006C\u006F\u006B\u00E1\u006C\u006E\u00ED\u0020\u006D\u011B\u006E\u011B\u002E'
WHEN mandant_id = 3 THEN  '\u0057\u0073\u007A\u0079\u0073\u0074\u006B\u0069\u0065\u0020\u0077\u0073\u006B\u0061\u017A\u006E\u0069\u006B\u0069\u0020\u0062\u0119\u0064\u0105\u0020\u006F\u0064\u0020\u0074\u0065\u0072\u0061\u007A\u0020\u0077\u0079\u0063\u0065\u006E\u0069\u0061\u006E\u0065\u0020\u0077\u0020\u0050\u004C\u004E\u002E'
WHEN mandant_id = 4 THEN  '\u0044\u0065\u0020\u0061\u0063\u0075\u006D\u0020\u00EE\u006E\u0061\u0069\u006E\u0074\u0065\u0020\u0076\u0061\u006C\u006F\u0072\u0069\u006C\u0065\u0020\u0069\u006E\u0064\u0069\u0063\u0061\u0074\u006F\u0072\u0069\u006C\u006F\u0072\u0020\u0076\u006F\u0072\u0020\u0066\u0069\u0020\u0061\u0066\u0069\u015F\u0061\u0074\u0065\u0020\u00EE\u006E\u0020\u006D\u006F\u006E\u0065\u0064\u0061\u0020\u006C\u006F\u0063\u0061\u006C\u0103\u002E'
WHEN mandant_id = 5 THEN 'Hodnoty v reportoch budú od teraz zobrazené v lokálnej mene.'
WHEN mandant_id = 6 THEN  '\u0056\u0072\u0069\u006A\u0065\u0064\u006E\u006F\u0073\u0074\u0069\u0020\u0107\u0065\u0020\u0073\u0065\u0020\u006F\u0064\u0020\u0073\u0061\u0064\u0061\u0020\u0070\u0072\u0069\u006B\u0061\u007A\u0069\u0076\u0061\u0074\u0069\u0020\u0075\u0020\u006C\u006F\u006B\u0061\u006C\u006E\u006F\u006A\u0020\u0076\u0061\u006C\u0075\u0074\u0069\u002E'
WHEN mandant_id = 7 THEN  '\u0044\u0065\u0020\u0061\u0063\u0075\u006D\u0020\u00EE\u006E\u0061\u0069\u006E\u0074\u0065\u0020\u0076\u0061\u006C\u006F\u0072\u0069\u006C\u0065\u0020\u0069\u006E\u0064\u0069\u0063\u0061\u0074\u006F\u0072\u0069\u006C\u006F\u0072\u0020\u0076\u006F\u0072\u0020\u0066\u0069\u0020\u0061\u0066\u0069\u015F\u0061\u0074\u0065\u0020\u00EE\u006E\u0020\u006D\u006F\u006E\u0065\u0064\u0061\u0020\u006C\u006F\u0063\u0061\u006C\u0103\u002E'
WHEN mandant_id = 8 THEN  '\u0421\u0442\u043E\u0439\u043D\u043E\u0441\u0442\u0438\u0442\u0435\u0020\u043D\u0430\u0020\u043F\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u0438\u0442\u0435\u0020\u0449\u0435\u0020\u0441\u0435\u0020\u043F\u043E\u043A\u0430\u0437\u0432\u0430\u0442\u0020\u0432\u0020\u043C\u0435\u0441\u0442\u043D\u0430\u0020\u0432\u0430\u043B\u0443\u0442\u0430\u0020\u0042\u0047\u004E\u002E'
END land_bez

FROM   dbp_view.v_mandant_spr_zu
) v01
JOIN dbp_msi.akt_msi_user_spr_zu v02
ON v01.spr_id = v02.spr_id
CROSS JOIN dbp_view.v_mandant v03;